INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5b7d39c10017d28c66750d6a92a9b6db748131ef/content/books/zizhi-tongjian/vol-292/year-0956/part-03/sources/library/tongjian-292-956-yangzhou-diplomacy/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003473；电子底本待考，分段待核", "id": "31a2e238-3147-5ada-a694-fdcdef0dcf25"}, {"title": "新五代史·卷十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5b7d39c10017d28c66750d6a92a9b6db748131ef/content/books/zizhi-tongjian/vol-292/year-0956/part-03/sources/library/xinwudaishi-12-huainan-956/source.txt", "note": "《新五代史》卷十二，段落 xin-wudaishi-b08f244b9241-p000378；EPUB电子本，纸本及异文待核", "id": "596e4c8e-f924-53b7-8b5d-645e9615242d"}, {"title": "新五代史·卷六十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5b7d39c10017d28c66750d6a92a9b6db748131ef/content/books/zizhi-tongjian/vol-292/year-0956/part-03/sources/library/xinwudaishi-67-chenman-misidentifies/source.txt", "note": "《新五代史》卷六十七，段落 xin-wudaishi-b08f244b9241-p003376；EPUB电子本，纸本及异文待核", "id": "af34714e-89b9-5742-afa9-288c8dcd6168"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3cf04308010988e93f2be2b3123fa7653105db77/content/books/zizhi-tongjian/vol-292/year-0956/part-02/sources/library/tongjian-292-956-shouzhou-chuzhou/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003472；电子底本待考，分段待核", "id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3cf04308010988e93f2be2b3123fa7653105db77/content/books/zizhi-tongjian/vol-292/year-0956/part-02/sources/library/jiuwudaishi-116-february-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002747；EPUB电子本，纸本及异文待核", "id": "5cb34744-9920-5ee5-acd6-d4771ea25ea7"}, {"title": "新五代史·卷四十九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3cf04308010988e93f2be2b3123fa7653105db77/content/books/zizhi-tongjian/vol-292/year-0956/part-02/sources/library/xinwudaishi-49-huangfu-captured/source.txt", "note": "《新五代史》卷四十九，段落 xin-wudaishi-b08f244b9241-p001910；EPUB电子本，纸本及异文待核", "id": "834d0d7c-ede9-5435-9849-30b8f8eaec05"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "王知朗", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐泗州牙将。956年二月奉李璟命携书求和，《通鉴》记送到徐州，《旧五代史》记到滁州，两种地点保留。生卒年未载。", "biography": null, "status": "draft", "id": "f620e724-f2ce-58a3-beed-e1fa08cde773"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "侯章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，947年二月任都头，在陕州与王晏、赵晖共同谋划反抗契丹。生卒年暂未录入。", "biography": null, "status": "draft", "id": "aafc9da4-682f-5473-bedf-46c919bc77c8"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "皇甫晖", "aliases": ["皇甫暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：皇甫晖。", "biography": null, "status": "draft", "id": "a1bbff11-3e05-52a8-a3c1-7e24adc029a5"}, {"name": "韩令坤", "aliases": ["韓令坤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "磁州武安人，后周侍卫马军都指挥使。955年十一月，奉柴荣命与其他十一名将领随李谷、王彦超出征南唐。生卒年未载。", "biography": null, "status": "draft", "id": "808ffe02-5578-55cc-8c1f-2b9823cfd253"}, {"name": "钟谟", "aliases": ["鍾謨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "会稽人，南唐吏部郎中。949年条下与李德明一起参与国政，史书称两人以辩才聪慧受到李璟宠信。与后文同名外交官的进一步经历按年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "ee7c4ab6-a8d3-5f0a-8b05-ede060c3934c"}, {"name": "李德明", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐尚书员外郎。949年条下与钟谟一起参与国政，史书记两人受李璟宠信，但不是魏岑的同党。生卒年尚未录入。", "biography": null, "status": "draft", "id": "3aa99691-05a6-5807-a0c3-f56c9cebb4f1"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "陈满", "aliases": ["陳滿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越苏州营田指挥使，《新五代史》称苏州候吏。956年建议吴程进攻常州，声称后周诏书已到；新史解释他误认了李璟派来的安抚使。两书解释及职名详略保留，未把报告直接当周诏真实送达。", "biography": null, "status": "draft", "id": "0376497b-7272-5ea0-9d79-ff271ac0aea7"}, {"name": "吴程", "aliases": ["吳程"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "山阴人，吴越丞相。947年十二月鲍修让将李仁达首级送到钱塘后，钱弘倧任吴程主持威武节度事务。生卒年未载。", "biography": null, "status": "draft", "id": "70950e94-6804-5b3e-afb7-43c0ab271dea"}, {"name": "元德昭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "危仔倡之子。946年吴越出兵救福州时，钱弘佐把军事谋划交给他。其姓名与父亲异姓按史书记载保留，不据此猜测改姓原因或收养关系；生卒年未载。", "biography": null, "status": "draft", "id": "3f40b6ff-27d0-5eae-a8f2-983b144f4081"}, {"name": "鲍修让", "aliases": ["鮑修讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越东南安抚使。947年钱弘佐派他率军驻守福州。生卒年未载。", "biography": null, "status": "draft", "id": "10a9b07f-dbdb-57a9-b923-561e2cfa6d86"}, {"name": "罗晟", "aliases": ["羅晟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越中直都指挥使。956年二月钱弘俶派吴程督鲍修让、罗晟赴常州。生卒年未载。", "biography": null, "status": "draft", "id": "19e44dec-b085-579c-821d-0087cde81018"}, {"name": "白延遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后晋护圣指挥使。946年六月受命与王彦超带所属十营兵赴邢州。生卒年未载；不与皇甫遇等姓名相近将领混同。", "biography": null, "status": "draft", "id": "175ec9b6-d0c6-53ca-985e-f818a4d10d20"}, {"name": "贾崇", "aliases": ["賈崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐侍卫都虞候。944年正月条下记其求见李璟，反对限制群臣奏事。自称事奉先帝三十年，此处不据时长倒推出任官年。生卒年未载。", "biography": null, "status": "draft", "id": "94f3a33b-2ca1-5bfd-9b97-4333588ff604"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "陈泽", "aliases": ["陳澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐鄂州长山寨将领。956年二月王逵奏报攻取该寨，将陈泽等俘获并献送。生卒年未载。", "biography": null, "status": "draft", "id": "73b85c3f-c71d-5fe2-a9a0-aeb85bd2ad9f"}, {"name": "耿谦", "aliases": ["耿謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐天长制置使。956年二月，赵匡胤奏报其归降。《通鉴》与《旧五代史》对所得粮草记二十余万、二千余万，数量及单位待核，未据差数另造两次归降。", "biography": null, "status": "draft", "id": "f1156219-85c3-585a-80d3-c4f8be9cbfc8"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李璟派王知朗送信，请停战修好，并愿奉柴荣为兄长、岁输财物", "start_year": 956, "end_year": 956, "time_original": "956年二月甲戌奏报以前，具体使行日未载", "dynasty": "五代十国", "description": "李璟以唐皇帝身份致书大周皇帝，派王知朗送信，提出停战修好、把柴荣视作兄长来侍奉，并每年输送财物助军费。《通鉴》记书信到徐州，旧史记到滁州。兄事是求和条件，不是两人已结为血亲或已达成外交约定。", "phases": [], "location_name": "南唐至徐州；旧史记滁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "03a7917d-d54e-5b90-a2f1-4ea3d708eb1d"}, {"title": "徐州奏报南唐求和信，柴荣没有答复", "start_year": 956, "end_year": 956, "time_original": "956年二月甲戌奏报，未答复的具体处置时点未另载", "dynasty": "五代十国", "description": "徐州奏报南唐求和信，柴荣没有答复。", "phases": [], "location_name": "徐州至后周行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dfe71080-067d-530f-8632-c8ec64977941"}, {"title": "柴荣命侯章等攻击寿州水寨，将壕水引入淝水", "start_year": 956, "end_year": 956, "time_original": "956年二月戊寅", "dynasty": "五代十国", "description": "柴荣命侯章等攻击寿州水寨，将壕水引入淝水。", "phases": [], "location_name": "寿州水寨、壕西北隅至淝水", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "419bf200-a250-5ad3-a356-e55403b6bdc7"}, {"title": "赵匡胤遣使献送皇甫晖等，皇甫晖重伤卧见柴荣", "start_year": 956, "end_year": 956, "time_original": "956年二月滁州夺取之后，献见具体日未载", "dynasty": "五代十国", "description": "赵匡胤遣使献送皇甫晖等，皇甫晖重伤卧见柴荣。", "phases": [], "location_name": "后周行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fbf1dbfb-5380-5b86-bf1f-42eb597e7da2"}, {"title": "皇甫晖向柴荣说明自己并非不忠，并称赞周兵精锐、赵匡胤勇猛", "start_year": 956, "end_year": 956, "time_original": "956年二月献见时", "dynasty": "五代十国", "description": "皇甫晖向柴荣说明自己并非不忠，并称赞周兵精锐、赵匡胤勇猛。", "phases": [], "location_name": "后周行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "616213f1-9ba6-5de0-9c13-dd7a51cf56df"}, {"title": "柴荣释放皇甫晖", "start_year": 956, "end_year": 956, "time_original": "956年二月献见之后，《旧五代史》乙亥条附释放", "dynasty": "五代十国", "description": "柴荣释放皇甫晖。", "phases": [], "location_name": "后周行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a2dc82fc-ae15-5b73-a80d-71b4103b24c4"}, {"title": "皇甫晖获释数日后去世", "start_year": 956, "end_year": 956, "time_original": "956年二月献见获释后数日，具体死亡日未载", "dynasty": "五代十国", "description": "皇甫晖获释数日后去世。", "phases": [], "location_name": "获释后具体地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2640cd40-3f61-584d-9047-4e3148f4b03a"}, {"title": "柴荣命韩令坤等突袭扬州，禁止残害百姓", "start_year": 956, "end_year": 956, "time_original": "956年二月己卯", "dynasty": "五代十国", "description": "柴荣命韩令坤等突袭扬州，禁止残害百姓。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9b646087-4e79-52a6-a44e-2e827731cc34"}, {"title": "柴荣派人与李氏族人共同看守陵寝", "start_year": 956, "end_year": 956, "time_original": "956年二月己卯袭扬州部署所附，具体守护起日未载", "dynasty": "五代十国", "description": "柴荣派人与李氏族人共同看守陵寝。", "phases": [], "location_name": "南唐李氏陵寝，具体地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "752d3d63-3046-540d-9098-bbec7c029dcd"}, {"title": "李璟派钟谟、李德明奉表称臣求和，并送礼物和犒军物资", "start_year": 956, "end_year": 956, "time_original": "956年二月壬午到寿州以前，具体派遣日未载", "dynasty": "五代十国", "description": "李璟派钟谟、李德明奉表称臣请求停战，送御服、茶药、金器千两、银器五千两、缯锦二千匹及犒军牛五百头、酒二千斛。数字按主书保存，旧史详略另列，不当作已经订立和约。", "phases": [], "location_name": "南唐至寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "61dbd4e3-e333-51da-95b2-3c3620d5413b"}, {"title": "钟谟、李德明到寿州城下，柴荣展示军容接见", "start_year": 956, "end_year": 956, "time_original": "956年二月壬午", "dynasty": "五代十国", "description": "钟谟、李德明到寿州城下，柴荣展示军容接见。", "phases": [], "location_name": "寿州城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "849e356a-6b4b-5063-b9dc-6cc5c106b3e0"}, {"title": "柴荣拒绝使者游说罢兵，要求李璟亲自谢罪，并以攻金陵施压", "start_year": 956, "end_year": 956, "time_original": "956年二月壬午接见时", "dynasty": "五代十国", "description": "柴荣指责李璟从海路联络契丹而未与后周修好，要求李璟亲自来见并谢罪，否则威胁进军金陵、取府库劳军。钟谟、李德明惧怕不敢答辩。这是接见中的责难、要求和威胁，不是当时已经攻陷金陵或取得其府库。", "phases": [], "location_name": "寿州行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a826a9fd-d5b2-58ce-8faa-37d29185e99d"}, {"title": "钱弘俶派兵屯边，等待后周命令", "start_year": 956, "end_year": 956, "time_original": "956年二月进常州之前，具体屯兵日未载", "dynasty": "五代十国", "description": "钱弘俶派兵屯边，等待后周命令。", "phases": [], "location_name": "吴越边境", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "eb821aec-a99c-5412-b000-d97ad880d578"}, {"title": "陈满向吴程建议乘南唐受惊、常州无备时出兵", "start_year": 956, "end_year": 956, "time_original": "956年二月吴越出军之前", "dynasty": "五代十国", "description": "陈满向吴程建议乘南唐受惊、常州无备时出兵。", "phases": [], "location_name": "吴越苏州及朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6871fb54-f867-54a0-9ca5-7caf46efb583"}, {"title": "陈满声称周诏已到，吴程据此向钱弘俶请求出兵", "start_year": 956, "end_year": 956, "time_original": "956年二月癸未出军以前", "dynasty": "五代十国", "description": "当时李璟派诏安抚江阴吏民，陈满却告吴程“周诏已至”，吴程据此请求钱弘俶立即出兵。《新五代史》解释为陈满未识别李璟的使者而误认，报告不能当作后周诏书实际到达的证明。", "phases": [], "location_name": "江阴、吴越朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ff331390-5c0f-59f5-b289-ba8f30659116"}, {"title": "元德昭担心孤军入境，主张暂等，吴程坚持出兵，钱弘俶采纳吴程", "start_year": 956, "end_year": 956, "time_original": "956年二月癸未出军以前", "dynasty": "五代十国", "description": "元德昭认为南唐不可轻视，若吴越进入南唐而周军不到，将无人协力，宜先等候。吴程坚持时机不可失，钱弘俶最终决定出兵。这里只记录意见分歧，不据此建两人的终身敌对关系。", "phases": [], "location_name": "吴越朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "84060398-90be-5985-ae8c-301a96dc0205"}, {"title": "钱弘俶派吴程督鲍修让、罗晟进军常州", "start_year": 956, "end_year": 956, "time_original": "956年二月癸未", "dynasty": "五代十国", "description": "钱弘俶派吴程督鲍修让、罗晟进军常州。", "phases": [], "location_name": "吴越至常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c5f02d75-f2b0-5678-a493-2f99113477db"}, {"title": "吴程称元德昭反对出师引发士卒怒言，钱弘俶藏护元德昭并捕议论者", "start_year": 956, "end_year": 956, "time_original": "956年二月出军之际，具体日未另载", "dynasty": "五代十国", "description": "吴程称元德昭反对出师引发士卒怒言，钱弘俶藏护元德昭并捕议论者。", "phases": [], "location_name": "吴越府中及军队", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f7202608-404f-5e4b-b9dd-ca5eac961c76"}, {"title": "韩令坤派白延遇骑兵先入扬州，随后率军到达", "start_year": 956, "end_year": 956, "time_original": "956年二月乙酉", "dynasty": "五代十国", "description": "韩令坤派白延遇骑兵先入扬州，随后率军到达。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a11283da-b775-5aae-88ad-2e5b81317f08"}, {"title": "贾崇焚烧扬州官府民舍，弃城南逃", "start_year": 956, "end_year": 956, "time_original": "956年二月乙酉周军入城时", "dynasty": "五代十国", "description": "贾崇焚烧扬州官府民舍，弃城南逃。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5dc388d6-0349-5814-8a6d-9b8e664cffa2"}, {"title": "冯延鲁剃发穿僧服躲入佛寺，被周军捕获", "start_year": 956, "end_year": 956, "time_original": "956年二月乙酉扬州入城后", "dynasty": "五代十国", "description": "冯延鲁剃发穿僧服躲入佛寺，被周军捕获。", "phases": [], "location_name": "扬州佛寺，具体寺名未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ebc05890-0fd6-5e5b-a58c-54fde7e2fc84"}, {"title": "韩令坤安抚扬州民众，使其留居安定", "start_year": 956, "end_year": 956, "time_original": "956年二月扬州入城之后", "dynasty": "五代十国", "description": "韩令坤安抚扬州民众，使其留居安定。", "phases": [], "location_name": "扬州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7ddd220b-07e1-52d7-a49d-95ec870868e6"}, {"title": "王逵奏报攻取鄂州长山寨，俘获陈泽等", "start_year": 956, "end_year": 956, "time_original": "956年二月庚寅奏报，具体攻取日未载", "dynasty": "五代十国", "description": "王逵奏报攻取鄂州长山寨，俘获陈泽等。", "phases": [], "location_name": "鄂州长山寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "198df53e-906e-549c-8474-46403759bf7b"}, {"title": "赵匡胤奏报天长制置使耿谦归降，并取得粮草", "start_year": 956, "end_year": 956, "time_original": "956年二月辛卯奏报，具体归降日未另列", "dynasty": "五代十国", "description": "赵匡胤奏报南唐天长制置使耿谦归降，取得刍粮二十余万。旧史同日记粮草二千余万，两者差异很大，数字与计量单位待校，不相加、不擅自换成现代粮食重量。", "phases": [], "location_name": "天长", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "94699766-a0e7-5d94-8de6-82917dd64ab8"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

