SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "李璟以唐皇帝身份致书大周皇帝，派王知朗送信，提出停战修好、把柴荣视作兄长来侍奉，并每年输送财物助军费。《通鉴》记书信到徐州，旧史记到滁州。兄事是求和条件，不是两人已结为血亲或已达成外交约定。", "citation": "卷292·显德三年（956年二月及相关追述）·zztj-v292-y0956-p015·原文件第88行", "note": "原文：唐主遣泗州牙将王知朗赍书抵徐州，称：“唐皇帝奉书大周皇帝，请息兵修好，愿以兄事帝，岁输货财以助军费。”；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "859a002d-14e5-5bf4-b477-e977a4401f96", "subject_id": "03a7917d-d54e-5b90-a2f1-4ea3d708eb1d", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年二月甲戌奏报以前，具体使行日未载", "citation": "卷292·显德三年（956年二月及相关追述）·zztj-v292-y0956-p015·原文件第88行", "note": "原文：唐主遣泗州牙将王知朗赍书抵徐州，称：“唐皇帝奉书大周皇帝，请息兵修好，愿以兄事帝，岁输货财以助军费。”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "67bbfc76-0ce7-5b74-a82e-866c4a1e4caa", "subject_id": "03a7917d-d54e-5b90-a2f1-4ea3d708eb1d", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "person", "field_path": "description", "claim_text": "李璟：派使送信提出停战和输财条件。", "citation": "卷292·显德三年（956年二月及相关追述）·zztj-v292-y0956-p015·原文件第88行", "note": "原文：唐主遣泗州牙将王知朗赍书抵徐州，称：“唐皇帝奉书大周皇帝，请息兵修好，愿以兄事帝，岁输货财以助军费。”；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "cc7c10ee-7929-56d3-9bec-fe40e6d9d847", "subject_id": "6bf72971-88c3-5187-8f25-98cde2a9554a", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李璟：派使送信提出停战和输财条件。", "citation": "卷292·显德三年（956年二月及相关追述）·zztj-v292-y0956-p015·原文件第88行", "note": "原文：唐主遣泗州牙将王知朗赍书抵徐州，称：“唐皇帝奉书大周皇帝，请息兵修好，愿以兄事帝，岁输货财以助军费。”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "bdf3a6be-4698-5af0-b06d-d1a23500fdf8", "subject_id": "f38c2963-75ab-57c1-885f-694d7c0ca79e", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "person", "field_path": "de